// Generated by Codex and not thoroughly checked for correctness.
func TestRegisteredRoutesEnforceSharedBudgetsAndExemptHealth(t *testing.T) {
	gin.SetMode(gin.TestMode)
	utils.Init("rate-limit-test-secret-with-enough-bytes")
	now := time.Now()
	service, err := ratelimit.New(ratelimit.DefaultConfig(), ratelimit.WithClock(func() time.Time { return now }))
	if err != nil {
		t.Fatal(err)
	}
	router := gin.New()
	if err := router.SetTrustedProxies(nil); err != nil {
		t.Fatal(err)
	}
	routes.RegisterRoutes(router, routes.Dependencies{Health: health.NewAPI(nil), Auth: auth.NewAuthHandler(nil, nil), RateLimits: service})
	// Both aliases consume the same budget; callback rejections need no provider.
	for index := range 11 {
		path := "/auth/github/callback"
		if index%2 == 0 {
			path = "/api/auth/github/callback"
		}
		want := http.StatusBadRequest
		if index == 10 {
			want = http.StatusTooManyRequests
		}
		assertRouteStatus(t, router, http.MethodGet, path, "", want)
	}
	for range 10 {
		if allowed, _ := service.Allow(ratelimit.Login, "192.0.2.1"); !allowed {
			t.Fatal("callback traffic consumed the separate login budget")
		}
	}
	for _, path := range []string{"/auth/github/login", "/api/auth/github/login"} {
		assertRouteStatus(t, router, http.MethodGet, path, "", http.StatusTooManyRequests)
	}
	token, err := utils.GenerateToken("owner@example.test", 42)
	if err != nil {
		t.Fatal(err)
	}
	for range 10 {
		service.Allow(ratelimit.General, "42")
	}
	for _, endpoint := range []struct{ method, path string }{
		{http.MethodGet, "/api/user/profile"},
		{http.MethodPut, "/api/user/cfhandle"},
		{http.MethodGet, "/api/user/cfverification-token"},
		{http.MethodGet, "/api/user/verify-cftoken"},
		{http.MethodGet, "/api/lists"},
		{http.MethodPost, "/api/lists"},
		{http.MethodGet, "/api/lists/1"},
		{http.MethodPut, "/api/lists/1"},
		{http.MethodDelete, "/api/lists/1"},
		{http.MethodPut, "/api/lists/1/item"},
		{http.MethodDelete, "/api/lists/1/item/1900A"},
	} {
		assertRouteStatus(t, router, endpoint.method, endpoint.path, token, http.StatusTooManyRequests)
		assertRouteStatus(t, router, endpoint.method, endpoint.path, "", http.StatusUnauthorized)
	}
	for range 12 {
		assertRouteStatus(t, router, http.MethodGet, "/health/live", "", http.StatusOK)
	}
	assertRouteStatus(t, router, http.MethodGet, "/health/ready", "", http.StatusServiceUnavailable)
}

func assertRouteStatus(t *testing.T, router *gin.Engine, method, path, token string, want int) {
	t.Helper()
	request := httptest.NewRequest(method, path, nil)
	request.RemoteAddr = "192.0.2.1:1234"
	if token != "" {
		request.Header.Set("Authorization", "Bearer "+token)
	}
	response := httptest.NewRecorder()
	router.ServeHTTP(response, request)
	if response.Code != want {
		t.Fatalf("%s %s status=%d, want %d; body=%s", method, path, response.Code, want, response.Body.String())
	}
	if want == http.StatusTooManyRequests && response.Header().Get("Retry-After") == "" {
		t.Fatal("missing Retry-After")
	}
}
